Tìm trục đối xứng của hình ảnh sau
}{
\begin{tikzpicture}
    % Vẽ thân nhà (hình chữ nhật)
    \draw[fill=blue!20] (-2,0) rectangle (2,-2);

    % Vẽ mái nhà (hình tam giác) với màu đỏ
    \draw[fill=red] (-2,0) -- (0,1.5) -- (2,0) -- cycle;

    % Vẽ cửa chính (hình chữ nhật nhỏ)
    \draw[fill=brown!50] (-0.5,-2) rectangle (0.5,-1);

    % Vẽ hai cửa sổ (hình vuông đối xứng)
    \draw[fill=white] (-1.5,-0.5) rectangle (-0.5,-1.5);
    \draw[fill=white] (0.5,-0.5) rectangle (1.5,-1.5);

    % Vẽ các đường chia cửa sổ
    \draw (-1,-0.5) -- (-1,-1.5);
    \draw (-1.5,-1) -- (-0.5,-1);
    \draw (1,-0.5) -- (1,-1.5);
    \draw (0.5,-1) -- (1.5,-1);
\end{tikzpicture}
}
